CREATE TABLE IF NOT EXISTS students (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_no VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, class_name VARCHAR(100) NOT NULL, email VARCHAR(120));
CREATE TABLE IF NOT EXISTS courses (id BIGINT AUTO_INCREMENT PRIMARY KEY, course_code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, teacher VARCHAR(80) NOT NULL, capacity INT NOT NULL, enrolled_count INT NOT NULL DEFAULT 0, credits DECIMAL(4,1) NOT NULL);
CREATE TABLE IF NOT EXISTS schedules (id BIGINT AUTO_INCREMENT PRIMARY KEY, course_id BIGINT NOT NULL, weekday INT NOT NULL, start_period INT NOT NULL, end_period INT NOT NULL, classroom VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS enrollments (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, course_id BIGINT NOT NULL, enrolled_at TIMESTAMP NOT NULL, CONSTRAINT uq_student_course UNIQUE(student_id,course_id));
CREATE TABLE IF NOT EXISTS grades (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, course_id BIGINT NOT NULL, score DECIMAL(5,2) NOT NULL, published BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS leave_requests (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, status VARCHAR(20) NOT NULL, review_comment VARCHAR(500));
CREATE TABLE IF NOT EXISTS attendance_status (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, location VARCHAR(120), remark VARCHAR(500), updated_at TIMESTAMP NOT NULL);
